<h1>Management profiles</h1><p>Standalone public leadership profiles are not staff records. Published profiles require a public management-photo media ID.</p><?php foreach(session('errors')??[] as $error): ?><p><?= esc($error) ?></p><?php endforeach ?>
<ul><?php foreach($profiles as $profile): ?><li><a href="?id=<?= esc($profile['id']) ?>"><?= esc($profile['full_name']) ?></a> — <?= esc($profile['status']) ?><form class="inline-form" method="post" action="<?= site_url('tenant/website/institutional/management/'.$profile['id'].'/archive') ?>"><?= csrf_field() ?><button>Archive</button></form></li><?php endforeach ?></ul>
<form method="post" action="<?= site_url('tenant/website/institutional/management') ?>"><?= csrf_field() ?><?php if($selected): ?><input type="hidden" name="id" value="<?= esc($selected['id']) ?>"><?php endif ?><label>Name <input name="full_name" required value="<?= esc(old('full_name',$selected['full_name']??'')) ?>"></label><label>Designation <input name="title" required value="<?= esc(old('title',$selected['title']??'')) ?>"></label><label>Photo media ID <input name="photo_media_id" required inputmode="numeric" value="<?= esc(old('photo_media_id',$selected['photo_media_id']??'')) ?>"></label><label>Biography <textarea name="bio" required><?= esc(old('bio',$selected['bio']??'')) ?></textarea></label><label>Order <input name="sort_order" type="number" min="0" required value="<?= esc(old('sort_order',$selected['sort_order']??0)) ?>"></label><label>Status <select name="status"><?php foreach(['draft','published','archived'] as $status): ?><option<?= old('status',$selected['status']??'draft')===$status?' selected':'' ?>><?= esc($status) ?></option><?php endforeach ?></select></label><button>Save profile</button></form>
<h2>Reusable management photos</h2><ul><?php foreach($media as $file): ?><li>ID <?= esc($file['id']) ?> — <?= esc($file['original_name']) ?> — <?= esc($file['visibility']) ?></li><?php endforeach ?></ul><?= $this->endSection() ?>
